import sys
import requests
import json
import hashlib
from urllib.parse import urljoin

def get_package_info(package):
    try:
        response = requests.get(f"https://pypi.org/pypi/{package}/json")
        response.raise_for_status()
        data = response.json()
        return data
    except Exception as e:
        print(f"Error fetching package info: {e}", file=sys.stderr)
        sys.exit(1)

def get_sdist_url(data):
    try:
        sdist_url = next(url for url in data['info']['urls'] if url.get('packagetype') == 'sdist')
        return sdist_url['url']
    except Exception as e:
        print(f"Error finding sdist URL: {e}", file=sys.stderr)
        sys.exit(1)

def download_archive(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.content
    except Exception as e:
        print(f"Error downloading archive: {e}", file=sys.stderr)
        sys.exit(1)

def generate_fingerprint(archive_bytes):
    return hashlib.sha256(archive_bytes).hexdigest()

def write_manifest(package, data, archive_bytes):
    try:
        filename = data['info']['urls'][0]['filename']
        fingerprint = generate_fingerprint(archive_bytes)
        with open(f"{package}-manifest.txt", "w") as f:
            f.write(f"name: {data['info']['name']}\n")
            f.write(f"version: {data['info']['version']}\n")
            f.write(f"filename: {filename}\n")
            f.write(f"fingerprint: {fingerprint}\n")
    except Exception as e:
        print(f"Error writing manifest: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python pkg_manifest.py <package>", file=sys.stderr)
        sys.exit(1)

    package = sys.argv[1]
    data = get_package_info(package)
    sdist_url = get_sdist_url(data)
    archive_bytes = download_archive(sdist_url)
    write_manifest(package, data, archive_bytes)

if __name__ == "__main__":
    main()

